import json, collections
rows=[json.loads(l) for l in open('tool_traces.jsonl')]
tests=[r for r in rows if r['event'] in ('run_tests','grade')]
print('run_tests+grade:', len(tests))
to=collections.Counter(); rc=collections.Counter(); reasons=collections.Counter(); secs=[]
counts=collections.Counter()
for r in tests:
    to[r.get('timeout')]+=1
    rc[r.get('returncode')]+=1
    reasons[r.get('reason')]+=1
    if 'seconds' in r: secs.append(r['seconds'])
    c=r.get('counts') or {}
    counts[json.dumps(c,sort_keys=True)]+=1
print('timeout dist:', dict(to))
print('returncode dist:', dict(rc))
print('reason dist:', dict(reasons))
print('seconds: n=%d min=%.2f max=%.2f mean=%.2f'%(len(secs),min(secs),max(secs),sum(secs)/len(secs)) if secs else 'no seconds')
print('junit counts dist:')
for k,v in counts.most_common(20): print('  ',v,k)
"

