import json, collections
tt=[json.loads(l) for l in open('tool_traces.jsonl')]
orig={r['trajectory_id']:r['source_sha256'] for r in tt if r['event']=='reset'}
grades=[r for r in tt if r['event']=='grade']
edits=collections.defaultdict(set)
for r in tt:
    if r['event']=='replace_source' and r.get('result')=='Edit applied.':
        edits[r['trajectory_id']].add(r['source_sha256'])
print('%-12s %-6s %-8s %-8s %s'%('case','reward','edited','==orig','n'))
agg=collections.defaultdict(lambda: collections.Counter())
for g in grades:
    t=g['trajectory_id']; c=g['case_id']
    same = g['source_sha256']==orig[t]
    agg[c][(g['reward'], 'unedited' if same else 'edited')]+=1
for c in sorted(agg, key=lambda x:(x.split('-')[0],int(x.split('-')[1]))):
    print('%-12s %s'%(c, dict(agg[c])))
"

